INSERT INTO site_news (title, body, published, created_at) VALUES
('Пуш-уведомления в приложении TRADERKA',
 'В мобильном приложении появились пуш-уведомления. Включите их одной кнопкой на главном экране, и новые посты и ежедневные сводки AiTKA будут приходить на телефон, даже когда сайт закрыт. На iPhone уведомления работают в приложении, добавленном на экран «Домой». Выключить их можно в любой момент той же кнопкой.',
 FALSE, NOW() - INTERVAL '3 minutes'),
('AiTKA торгует на тренировочной бирже сам',
 'Наш ИИ-бот AiTKA вышел на тренировочную биржу и открывает сделки на виртуальные деньги. Он следит за движением монет за сутки, ограничивает риск стоп-лоссом и тейк-профитом и закрывает позиции по времени. Его сделки видны в ленте последних сделок и в рейтинге биржи. Это игра, а не подсказка, что покупать.',
 FALSE, NOW() - INTERVAL '2 minutes'),
('Мои монеты и мини-кошелёк в мобильной версии',
 'В «Котировках» мобильной версии появился блок «Мои монеты»: Bitcoin и Ethereum показываются всегда, а ещё до четырёх монет вы выбираете сами. Выбор привязан к аккаунту и переносится между устройствами. На главной добавлен мини-кошелёк с количеством TKA, USDT и общим результатом на бирже.',
 FALSE, NOW() - INTERVAL '1 minutes');